use rax::user::{image::pe::{RvaSource,RvaFault,exports::{ExportDirectory,ExportTarget}},mm::AddressSpace,windows::{memory::Mem,process::{Proc,WindowsConfig,WindowsProcess,RunStatus}}};
use serde_json::json;
struct Guest<'a>{space:&'a AddressSpace,base:u64,size:u64}
impl RvaSource for Guest<'_>{fn read_rva(&self,rva:u64,out:&mut[u8])->Result<(),RvaFault>{if rva.checked_add(out.len()as u64).is_none_or(|end|end>self.size){return Err(RvaFault{rva});}self.space.rd(self.base+rva,out).map_err(|_|RvaFault{rva})}}
fn state_address(p:&Proc)->u64{let m=&p.modules.list[0];let src=Guest{space:&p.space,base:m.base,size:m.size};let ex=ExportDirectory::read(&src,m.exports).unwrap().unwrap();let mut found=None;for(name,index)in ex.names(&src).unwrap(){if name==b"rax_thread_object_state"||name==b"_rax_thread_object_state"{let Some(ExportTarget::Rva(rva))=ex.by_index(&src,index).unwrap()else{panic!("state export is not data")};assert!(found.is_none());found=Some(m.base+u64::from(rva));}}found.unwrap()}
fn main(){let program=std::env::args().nth(1).unwrap();let mut cfg=WindowsConfig::new(&program,vec![]);cfg.native_libraries=true;cfg.arena_bytes=512<<20;cfg.slice_insns=1<<20;cfg.drives=rax::user::windows::fs::DriveMap::from_host().unwrap();let mut process=WindowsProcess::spawn(cfg).unwrap();let state=state_address(process.state());assert_eq!(process.state().space.u32(state).unwrap(),0x52415854);let cancel=std::sync::atomic::AtomicBool::new(false);let mut terminal=String::from("DiagnosticBudgetExhausted");let mut turns=0;for turn in 0..5000{turns=turn+1;let status=process.run_slice(1,&cancel);if let RunStatus::Complete(result)=status{terminal=format!("{result:?}");break;}if matches!(status,RunStatus::Blocked){std::thread::sleep(std::time::Duration::from_millis(1));}}let p=process.state();let values:Vec<_>=(0..64).map(|i|p.space.u32(state+i*4).unwrap()).collect();println!("{}",json!({"schema":"rax-installed-thread-object-attributes-v1","program":program,"terminal":terminal,"turns":turns,"state_address":state,"observations":values,"completed_cases":values[1],"failure_index":values[6],"assertions":values[10],"threads":p.threads.values().map(|t|json!({"tid":t.tid,"pc":t.cpu.pc(),"state":format!("{:?}",t.state)})).collect::<Vec<_>>()}));}
